      targetWords: ["fertile", "intelligence", "abstract", "wheels", "furniture", "clay", "cloth", "deserved", "annual", "religious", "shells", "feathers", "curtain", "ideal", "shore", "flood", "obtained", "grave", "romantic", "nowadays"],
