        { id: "rc_29_5", question: "What did the Egyptians do for their king and queen?", options: ["They built Osiris and Isis a pyramid.", "They gave them horses.", "They went overseas.", "They made them cars."], answer: "They built Osiris and Isis a pyramid." }
